import{_ as o,l as i,o as e,c as l,v as t,p as s,x as n,d as E,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"协整破裂","description":"","frontmatter":{"title":"协整破裂","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cointegration-break.md","filePath":"quant/cointegration-break.md","lastUpdated":1789023840000}'),d={name:"quant/cointegration-break.md"};function A(c,a,B,u,m,_){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="协整破裂" tabindex="-1">协整破裂 <a class="header-anchor" href="#协整破裂" aria-label="Permalink to &quot;协整破裂&quot;">​</a></h1><div class="epigraph"><p>若协整关系本身会在未知时点发生水平或斜率转换，标准残差单位根检验会把「带断裂的协整」误判成「根本没有协整」。</p><footer>—— Gregory &amp; Hansen, Residual-based Tests for Cointegration in Models with Regime Shifts, Journal of Econometrics, 1996</footer></div><p><a href="/quant/kalman-hedge">上一课</a>把时变对冲比写成随机游走状态，可交易信号必须用预测步；滤波残差平稳不能用 Johansen 的 \\(p\\) 值证明。Kalman 适应的是缓慢漂移的 \\(\\beta\\)，不是未知时点的机制转换。缺口是曾经协整、后来断了：水平漂移、趋势转换、或连斜率一起换。Engle–Granger / Johansen 的全样本直线会把两段均衡揉成一条过宽的带，交易规则却仍把旧 \\(\\beta\\) 当成均衡。本课写破裂检验与交易是两件事。不重推滤波递推。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设对数价格 \\(y_t\\)、\\(x_t\\) 都是 I(1)。Engle–Granger 的零假设是「无协整」：残差 \\(\\hat{u}_t=y_t-\\hat\\alpha-\\hat\\beta x_t\\) 仍是单位根。若真实关系在 \\(t=\\tau\\) 处从 \\(( \\alpha_1,\\beta_1 )\\) 跳到 \\(( \\alpha_2,\\beta_2 )\\)，全样本一条直线拟合会把两段均衡揉成一条过宽的带，残差看起来像随机游走。ADF 或 Phillips–Ouliaris 于是拒绝不了「无协整」，或者更糟：样本前半段显著、你已经开仓，后半段系数变了，残差朝一个方向走、再也不回来。</p><p>配对交易里这表现为「价差的历史标准差」突然失效。公司行为（分拆、增发、指数调入调出）、行业监管、会计口径、以及 2008、2020 这类宏观机制转换，都会让 \\(\\beta\\) 不再是同一个数。问题不是要不要协整，而是：在未知断裂下，残差平稳性检验的势会塌掉，而交易规则却仍把旧 \\(\\beta\\) 当成均衡。</p><h3 id="水平漂移、趋势与机制转换" tabindex="-1">水平漂移、趋势与机制转换 <a class="header-anchor" href="#水平漂移、趋势与机制转换" aria-label="Permalink to &quot;水平漂移、趋势与机制转换&quot;">​</a></h3><p>Gregory–Hansen 把备择写成三类。水平漂移（level shift）：截距在 \\(\\tau\\) 处跳一下，\\(\\beta\\) 不变，像一只股票除权或基准利率台阶。趋势转换：确定性趋势的斜率也变。机制转换（regime shift）：截距与斜率都变，这是配对里最常见、也最伤的一种——对冲比本身换了。检验统计量是在可能的断裂日期上取 inf 的残差 ADF（或 \\(Z_t\\)、\\(Z_\\alpha\\)），临界值比标准 Engle–Granger 更宽，因为搜索断裂本身消耗了自由度。</p><p><span class="marginnote">「价差 Z-score 到 2 就开仓」默认协整向量在形成期内不变。Gregory–Hansen 要问的是：形成期内部是否已经发生过一次水平或斜率转换。若发生过，历史标准差被两段制度拉大，阈值看起来很保守，实则对当前制度过松。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实务上不要只用全样本 EG。至少做三层。第一层：滚动窗口 Engle–Granger 或 Johansen，看 \\(\\hat\\beta\\) 与残差半衰期是否稳定。第二层：在候选窗口上跑 Gregory–Hansen 的 ADF*、\\(Z_t^\\ast\\)，并报告估计的 \\(\\hat\\tau\\)。第三层：把 \\(\\hat\\tau\\) 附近当成不可交易区间——不是把断裂日当天的残差当成「更大的 alpha」。Hansen 1992 年对 I(1) 回归参数不稳定性的检验、Bai–Perron 的多断裂估计，可以作辅助，但协整残差的单位根零假设与普通回归的参数稳定性零假设不是同一个检验。</p><p>误差修正模型在断裂后必须重估。旧的</p> \\[\\Delta y_t=\\lambda(y_{t-1}-\\alpha-\\beta x_{t-1})+\\cdots \\]<p>中，\\(\\lambda\\) 的符号与幅度只在旧均衡附近有意义。断裂后若仍用旧 \\((\\alpha,\\beta)\\)，误差修正项会变成一个带漂移的错误信号，看起来像「价差还会回归」，其实是在用错误的原点。Johansen 系统在确定性项带断裂时也需要 Hansen 或 Johansen–Mosconi–Nielsen 一类设定，不能把 rank 检验的 p 值直接当成交易许可。</p><h3 id="从检验到仓位-确认滞后" tabindex="-1">从检验到仓位：确认滞后 <a class="header-anchor" href="#从检验到仓位-确认滞后" aria-label="Permalink to &quot;从检验到仓位：确认滞后&quot;">​</a></h3><p>检出断裂有滞后。inf 型统计量要在一个修剪区间（常见是样本的 15%–85%）上搜索，\\(\\hat\\tau\\) 的置信带往往有好几周。交易上这意味着：当你在统计上「确认」破裂时，旧仓位可能已经沿着错误残差走出很远。因此规则应是预先规定的：残差突破形成期若干倍标准差且滚动 \\(\\beta\\) 的置信区间不再覆盖旧点，即减仓或平仓，而不是等论文里的 ADF* 过临界值。后者是事后诊断，不是盘中触发器。</p><p><span class="marginnote">把 Gregory–Hansen 的临界值表直接拿来当日内配对的停损线，是把渐近检验误当成滤波器。日频、周频上它有用；tick 上价格是带微观结构噪声的，单位根与协整的渐近理论要对 <a href="/quant/microstructure-noise">噪声</a> 另作处理。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>协整破裂伤策略的渠道有三条。识别错误：你交易的不是平稳价差，而是一段错误设定的 I(1) 残差，期望回归时间无限。拥挤平仓：同一对名字被许多账户用相近的 \\(\\beta\\) 对冲，断裂日大家同时认错，价差的一次性跳跃伴有流动性真空，见<a href="/quant/factor-crowding">因子拥挤</a> 在统计套利层的同类现象。样本内过拟合：在全样本上挑「看起来协整」的对，等价于对断裂点做了隐式选择，伪平稳的对在样本外会集中爆炸。</p><p>误差修正速度 \\(\\lambda\\) 本身也会变。危机里相关结构向 1 塌缩，\\(\\beta\\) 趋近于 1 但残差波动变大，半衰期估计会系统性偏短——你以为两天能回归，实际是共同因子主导下的假回归。Avellaneda–Lee 式的残差 OU 假设与协整是近亲：OU 的均值一旦漂移，Z-score 开仓就变成在错误的原点上加仓。</p><h3 id="为何「再等等会回归」特别危险" tabindex="-1">为何「再等等会回归」特别危险 <a class="header-anchor" href="#为何「再等等会回归」特别危险" aria-label="Permalink to &quot;为何「再等等会回归」特别危险&quot;">​</a></h3><p>I(1) 残差的局部路径可以像平稳过程一样走一段。这会诱使账户用时间止损的反面——「还没到持有期终点，再拿着」。Gregory–Hansen 的备择明确允许新均衡存在，但新均衡的位置对旧仓位是一笔已实现亏损，不是期权。若新 \\(\\beta\\) 对应基本面的永久变化（业务分拆、指数权重永久上调），期望回归为零。容量在这里是非线性的：小账户或许能在确认后按新协整再开；大账户的平仓本身就是把残差推得更远的冲击。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>检验的势在断裂靠近样本两端时很弱，修剪参数不是免费的。多断裂比单断裂更符合 2010 年代之后的市场，但多重搜索会进一步抬高临界值，小样本日频配对（一年约 250 点）很容易什么都检不出，却仍会亏钱。A 股还要处理涨跌停与停牌造成的伪断裂：价格冻结几天再跳开，残差 ADF 会被几个点主导。</p><p>成本与可交易性。断裂前后买卖价差往往同时变宽，按旧价差估算的「回归利润」在冲击后不再覆盖往返成本。借券失败、成份股权重调整日的一揽子交易，都会让 \\(\\beta\\) 在你无法成交的时点跳变。不要把「检出协整」写成可套利定理：无摩擦下的误差修正期望，减去<a href="/quant/effective-realized-spread">有效价差</a>与冲击之后，许多对的净期望为负。策略文档里应同时报告：无断裂子样本的残差半衰期、断裂窗口的最大不利偏移、以及假设冲击为 ADV 某比例时的容量上限。</p><p><span class="marginnote">Engle–Granger 与 Johansen 给出的是统计关系，不是法偿的收敛承诺。指数套利、ETF 申赎有制度上的收敛机制；普通股票对没有。把后者写成前者，是类别错误。</span></p>',26)),(e(),s(p,null,{default:n(()=>[h(r,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22I(1)%20%E4%BB%B7%E6%A0%BC%20y%2C%20x%22%5D%20--%3E%20EG%5B%22%E5%85%A8%E6%A0%B7%E6%9C%AC%20Engle-Granger%22%5D%0A%20%20EG%20--%3E%20R%5B%22%E6%AE%8B%E5%B7%AE%20u%22%5D%0A%20%20R%20--%3E%20ADF%5B%22%E6%A0%87%E5%87%86%20ADF%20%2F%20Phillips-Ouliaris%22%5D%0A%20%20ADF%20--%3E%7C%22%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%B9%B3%E7%A8%B3%22%7C%20TR%5B%22%E6%8C%89%E6%97%A7%20%CE%B2%20%E4%BA%A4%E6%98%93%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20P%20--%3E%20GH%5B%22Gregory-Hansen%20%E6%90%9C%E7%B4%A2%20%CF%84%22%5D%0A%20%20GH%20--%3E%20BRK%5B%22%E6%B0%B4%E5%B9%B3%20%2F%20%E6%96%9C%E7%8E%87%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20BRK%20--%3E%20STOP%5B%22%E6%97%A7%E4%BB%93%E8%A7%86%E4%B8%BA%E9%94%99%E8%AF%AF%E8%AE%BE%E5%AE%9A%22%5D%0A%20%20STOP%20--%3E%20RE%5B%22%E5%9C%A8%E6%96%B0%E7%AA%97%E5%8F%A3%E9%87%8D%E4%BC%B0%E5%8D%8F%E6%95%B4%22%5D%0A%20%20TR%20--%3E%7C%22%E6%9C%AA%E6%A3%80%E5%87%BA%E7%9A%84%E7%A0%B4%E8%A3%82%22%7C%20LOSS%5B%22%E6%AE%8B%E5%B7%AE%E5%8D%95%E8%BE%B9%E8%B5%B0%E6%89%A9%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>协整破裂是未知时点的水平或斜率转换；全样本残差单位根检验会把带断裂的协整误判为无协整，或让旧 \\(\\beta\\) 在断裂后继续当均衡。</li><li>Gregory–Hansen（1996）用 inf 型残差检验覆盖水平漂移、趋势转换与机制转换；临界值宽于 Engle–Granger，且 \\(\\hat\\tau\\) 有确认滞后。</li><li>交易规则应把滚动 \\(\\beta\\) 失稳与残差单边走扩当作减仓触发，而不是把 ADF* 当盘中信号。</li><li>拥挤平仓、价差走阔与冲击使断裂窗口的账面回归不可当作期望利润。</li><li>股票对没有指数套利那种制度收敛；新均衡可以永久偏离旧仓位。</li><li>出处：Gregory and Hansen, <em>Journal of Econometrics</em>, 1996；同作者 <em>Oxford Bulletin of Economics and Statistics</em>, 1996；Engle and Granger, <em>Econometrica</em>, 1987；Hansen, <em>Journal of Business &amp; Economic Statistics</em>, 1992。</li></ul>',2))])}const g=o(d,[["render",A]]);export{f as __pageData,g as default};
